+                "sign_convention": "table_rh",
+                "parts": [
+                    {
+                        "id": "base", "name": "table", "type": "table",
+                        "parts": [
+                            {
+                                "id": "a", "name": "A", "type": "rotary",
+                                "axis": [1.0, 0.0, 0.0],
+                                "pivot": [0.0, 12.5, -45.0],
+                                "travel": { "min": -110.0, "max": 30.0 },
+                                "zero_offset": 0.0,
+                                "rollover": false,
+                                "parts": [
